pod=aiops-f1-high-cpu; namespace=cloud-reference; trace=dtr_kubernetes_f1_v1; evidence_dir=delivery-evidence/kubernetes; evidence_path="$evidence_dir/f1-high-cpu.json"; started_at="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
cleanup(){ k3s kubectl -n "$namespace" delete pod "$pod" --ignore-not-found --wait=true >/dev/null 2>&1||true; }
