k3s kubectl -n "$namespace" run "$pod" --image='docker.io/nginxinc/nginx-unprivileged@sha256:27985295bdb22a1ef8f712863210bd5877c0f3006494a593e86b3fe0fa55467e' --restart=Never --labels="app=aiops-f1-high-cpu,aiops.site=las,decision-trace-id=$trace" --overrides='{"spec":{"automountServiceAccountToken":false,"securityContext":{"runAsNonRoot":true,"seccompProfile":{"type":"RuntimeDefault"}},"containers":[{"name":"aiops-f1-high-cpu","image":"docker.io/nginxinc/nginx-unprivileged@sha256:27985295bdb22a1ef8f712863210bd5877c0f3006494a593e86b3fe0fa55467e","command":["/bin/sh","-c","while :; do :; done"],"resources":{"requests":{"cpu":"150m","memory":"16Mi"},"limits":{"cpu":"200m","memory":"32Mi"}},"securityContext":{"allowPrivilegeEscalation":false,"readOnlyRootFilesystem":true,"capabilities":{"drop":["ALL"]}}}]}}' >/dev/null
