deadline=$(($(date +%s)+120)); alert_started_at=''; cpu=0
while test "$(date +%s)" -lt "$deadline"; do cpu="$(curl -fsS 'http://127.0.0.1:9090/api/v1/query?query=aiops_kubernetes_pod_cpu_millicores%7Bpod%3D%22aiops-f1-high-cpu%22%7D'|jq -r '.data.result[0].value[1] // 0')"; firing="$(curl -fsS 'http://127.0.0.1:9090/api/v1/alerts'|jq -r '[.data.alerts[]|select(.labels.alertname=="KubernetesLasPodHighCpu" and .state=="firing")]|length')"; if awk "BEGIN{exit !($cpu>=100)}"&&test "$firing" -gt 0;then alert_started_at="$(date -u +%Y-%m-%dT%H:%M:%SZ)";break;fi;sleep 5;done
test -n "$alert_started_at"; cleanup
recovery_deadline=$(($(date +%s)+60)); while test "$(date +%s)" -lt "$recovery_deadline";do firing="$(curl -fsS 'http://127.0.0.1:9090/api/v1/alerts'|jq -r '[.data.alerts[]|select(.labels.alertname=="KubernetesLasPodHighCpu" and .state=="firing")]|length')";test "$firing" -eq 0&&break;sleep 5;done;test "$firing" -eq 0;recovered_at="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
